//! Typestates for every solved pin, port and peripheral.
//!
//! @generated by `aethelgard-svd-hal` (AET-WO-1400). Do not edit: the regeneration
//! test compares every byte of this tree with the generator's output.
//!
//! - Solved topology of specification sha256 `a277c933439524885deb931b2b930555b74aa94aefbee7b34c83ddef73aa1196`.
//! - Register facts: `https://github.com/STMicroelectronics/cmsis-device-h7` at `8f922cdc7cc6de2344e75ddd657889f4ff761790`, `stm32h753xx.h` sha256 `4f6def439a9fa94705303fe227d34308048c44bd36263d311aa54cc94f8398f5`.
//! - Pin data: `STM32_open_pin_data` at `7d1f1514ed5583ec5007ad91236b4e1d377295b1`.
//!
//! Every register access goes through [`Registers`]. [`mmio`] is its only
//! implementation at real addresses and the crate's only `unsafe`. The Kani
//! harness in `proofs` implements it over a register image it owns.
//!
//! [`Board::take`] is the crate's one runtime check: a second call returns
//! `None`. Everything else that is illegal does not compile (`INV-02`).

use core::marker::PhantomData;
use core::sync::atomic::{AtomicBool, Ordering};

/// The register blocks this board touches.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Block {
    Rcc,
    GpioA,
    GpioB,
    I2c1,
    Spi1,
}

/// The lock on [`Registers`].
pub(crate) mod sealed {
    pub trait Sealed {}

    /// Only this crate can make one.
    pub struct Token(pub(crate) ());
}

const TOKEN: sealed::Token = sealed::Token(());

/// The one door to the hardware. Offsets are byte offsets into the block.
///
/// It is sealed, and every method takes a [`sealed::Token`] that only this
/// crate can make. So firmware can neither implement it, which would advance
/// the typestates on a stand-in, nor call it, which would reach a register
/// around them. Only the typestate API below can (`INV-02`; adversarial E2, E3).
///
/// `read8` and `write8` are single-byte accesses, for the SPI data registers
/// only: with frames of 8 bits or less, a 16- or 32-bit access to `SPI_TXDR` or
/// `SPI_RXDR` packs two or four frames on silicon (RM0433 Rev 9 §50.4.13) and
/// one in Renode 1.17.0, so only a byte access means the same on both.
pub trait Registers: sealed::Sealed {
    fn read(&mut self, token: sealed::Token, block: Block, offset: usize) -> u32;
    fn write(&mut self, token: sealed::Token, block: Block, offset: usize, value: u32);
    fn read8(&mut self, token: sealed::Token, block: Block, offset: usize) -> u8;
    fn write8(&mut self, token: sealed::Token, block: Block, offset: usize, value: u8);
    fn modify(&mut self, token: sealed::Token, block: Block, offset: usize, f: impl FnOnce(u32) -> u32) {
        let value = self.read(sealed::Token(()), block, offset);
        self.write(token, block, offset, f(value));
    }
}

/// Volatile access at the part's real base addresses. Never exercised by
/// the proof: Kani cannot own this memory (`architecture.md` §2.2).
pub mod mmio {
    use super::{Block, Registers, sealed};

    pub struct Mmio {
        _private: (),
    }

    impl Mmio {
        /// # Safety
        /// The caller runs on the part this crate was generated for, and no
        /// other `Mmio` exists.
        pub unsafe fn new() -> Self {
            Mmio { _private: () }
        }
    }

    const fn base(block: Block) -> usize {
        match block {
            Block::Rcc => 0x58024400,
            Block::GpioA => 0x58020000,
            Block::GpioB => 0x58020400,
            Block::I2c1 => 0x40005400,
            Block::Spi1 => 0x40013000,
        }
    }

    impl sealed::Sealed for Mmio {}

    impl Registers for Mmio {
        fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
            // SAFETY: a register of a peripheral that exists on this part.
            unsafe { core::ptr::read_volatile((base(block) + offset) as *const u32) }
        }
        fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
            // SAFETY: as for `read`.
            unsafe { core::ptr::write_volatile((base(block) + offset) as *mut u32, value) }
        }
        fn read8(&mut self, _: sealed::Token, block: Block, offset: usize) -> u8 {
            // SAFETY: as for `read`, one byte wide.
            unsafe { core::ptr::read_volatile((base(block) + offset) as *const u8) }
        }
        fn write8(&mut self, _: sealed::Token, block: Block, offset: usize, value: u8) {
            // SAFETY: as for `read`, one byte wide.
            unsafe { core::ptr::write_volatile((base(block) + offset) as *mut u8, value) }
        }
    }
}

