/// The most reads of `ISR` any one wait of a transfer makes before it gives up.
pub const I2C_WAIT_SPINS: u32 = 20_000;

/// Why a transfer gave up. A wait that expires names where; a transfer never
/// panics and never waits without a bound.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum I2cError {
    /// More than 255 bytes in a direction: `NBYTES` is eight bits.
    Length,
    /// `TXIS` never rose: the address went unanswered.
    Txis,
    /// `TC` never rose after the last byte written, before a repeated start.
    Tc,
    /// `RXNE` never rose: a byte of the read did not arrive.
    Rxne,
    /// `STOPF` never rose after the last byte.
    Stop,
}

/// Reads `ISR` at most `spins` times for any bit of `mask`.
fn i2c_wait<R: Registers>(r: &mut R, block: Block, isr: usize, mask: u32, spins: u32) -> bool {
    let mut n = 0;
    while n < spins {
        if r.read(TOKEN, block, isr) & mask != 0 {
            return true;
        }
        n += 1;
    }
    false
}

/// The most reads of `SR` any one wait of an SPI transfer makes before it gives up.
pub const SPI_WAIT_SPINS: u32 = 20_000;

/// The most frames one SPI transfer moves: an identity read is the command and
/// at most four bytes, and one transaction per device is all this crate makes.
pub const SPI_MAX_FRAMES: u32 = 8;

/// Why an SPI transfer gave up. It never panics and never waits without a bound.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SpiError {
    /// No frame, or more than [`SPI_MAX_FRAMES`]. No register was touched.
    Length,
    /// `SR.RXP` never rose: a frame's byte did not arrive.
    Rxp,
}

/// One 8-bit frame: `byte` out through `TXDR`, a wait of at most `spins` reads of
/// `SR` for `RXP`, then the byte in from `RXDR`. Both data accesses are one byte
/// wide ([`Registers`]). `None` when `RXP` never rose, and `RXDR` is then not
/// read: an empty FIFO.
fn spi_frame<R: Registers>(r: &mut R, block: Block, byte: u8, spins: u32) -> Option<u8> {
    r.write8(TOKEN, block, 0x20, byte);
    let mut n = 0;
    while n < spins {
        if r.read(TOKEN, block, 0x14) & 0x00000001 != 0 {
            return Some(r.read8(TOKEN, block, 0x30));
        }
        n += 1;
    }
    None
}

/// `PA0`, net `FLASH_CS`: a GPIO output.
pub struct PA0<M> {
    _mode: PhantomData<M>,
}

impl PA0<Unconfigured> {
    pub fn into_output<R: Registers>(self, r: &mut R) -> PA0<Output> {
        r.modify(TOKEN, Block::GpioA, 0x04, |v| v & !0x00000001);
        r.modify(TOKEN, Block::GpioA, 0x08, |v| v & !0x00000003);
        r.modify(TOKEN, Block::GpioA, 0x0c, |v| v & !0x00000003);
        r.write(TOKEN, Block::GpioA, 0x18, 0x00000001);
        r.modify(TOKEN, Block::GpioA, 0x00, |v| (v & !0x00000003) | 0x00000001);
        PA0 { _mode: PhantomData }
    }
}

impl PA0<Output> {
    pub fn set_high<R: Registers>(&mut self, r: &mut R) {
        r.write(TOKEN, Block::GpioA, 0x18, 0x00000001);
    }
    pub fn set_low<R: Registers>(&mut self, r: &mut R) {
        r.write(TOKEN, Block::GpioA, 0x18, 0x00010000);
    }
}

