/// `I2C1`. It starts only from `Clocked`, and only on its solved pins.
pub struct I2c1<S> {
    _state: PhantomData<S>,
}

impl I2c1<Clocked> {
    pub fn init<S: i2c1_speed::AtMostCeiling, R: Registers>(
        self,
        r: &mut R,
        _scl: PB6<AlternateFunction<4>>,
        _sda: PB7<AlternateFunction<4>>,
    ) -> I2c1<Enabled<S>> {
        r.modify(TOKEN, Block::I2c1, 0x00, |v| v & !0x00000001);
        r.write(TOKEN, Block::I2c1, 0x10, S::TIMINGR);
        r.modify(TOKEN, Block::I2c1, 0x00, |v| v | 0x00000001);
        I2c1 { _state: PhantomData }
    }
}

impl<S: i2c1_speed::AtMostCeiling> I2c1<Enabled<S>> {
    pub fn write_byte<R: Registers>(&mut self, r: &mut R, byte: u8) {
        r.write(TOKEN, Block::I2c1, 0x28, u32::from(byte));
    }
}

impl<S: i2c1_speed::AtMostCeiling> I2c1<Enabled<S>> {
    /// Writes `write`, then, if `read` is not empty, reads it back after a repeated
    /// start; or only writes; or only reads. Every wait is bounded by
    /// [`I2C_WAIT_SPINS`]. Returns the bytes read, or the wait that expired.
    pub fn transfer<R: Registers>(
        &mut self,
        r: &mut R,
        address: u8,
        write: &[u8],
        read: &mut [u8],
    ) -> Result<usize, I2cError> {
        self.transfer_within(r, address, write, read, I2C_WAIT_SPINS)
    }

    /// [`Self::transfer`] with its own bound on each wait, so the proof can use a
    /// small one.
    #[doc(hidden)]
    pub fn transfer_within<R: Registers>(
        &mut self,
        r: &mut R,
        address: u8,
        write: &[u8],
        read: &mut [u8],
        spins: u32,
    ) -> Result<usize, I2cError> {
        let (Ok(nw), Ok(nr)) = (u8::try_from(write.len()), u8::try_from(read.len())) else {
            return Err(I2cError::Length);
        };
        if nw == 0 && nr == 0 {
            return Ok(0);
        }
        let sadd = u32::from(address) << 1;
        let mut fail = None;
        let mut got = 0;
        if nw > 0 {
            let end = if nr == 0 { 0x02000000 } else { 0 };
            r.write(TOKEN, Block::I2c1, 0x04, sadd | (u32::from(nw) << 16) | 0x00002000 | end);
            for &byte in write {
                if !i2c_wait(r, Block::I2c1, 0x18, 0x00000002, spins) {
                    fail = Some(I2cError::Txis);
                    break;
                }
                r.write(TOKEN, Block::I2c1, 0x28, u32::from(byte));
            }
            if fail.is_none() && nr > 0 && !i2c_wait(r, Block::I2c1, 0x18, 0x00000040, spins) {
                fail = Some(I2cError::Tc);
            }
        }
        if fail.is_none() && nr > 0 {
            r.write(TOKEN, Block::I2c1, 0x04, sadd | 0x00000400 | (u32::from(nr) << 16) | 0x00002000 | 0x02000000);
            for slot in read.iter_mut() {
                if !i2c_wait(r, Block::I2c1, 0x18, 0x00000004, spins) {
                    fail = Some(I2cError::Rxne);
                    break;
                }
                *slot = u8::try_from(r.read(TOKEN, Block::I2c1, 0x24) & 0xFF).unwrap_or(0);
                got += 1;
            }
        }
        if fail.is_none() && !i2c_wait(r, Block::I2c1, 0x18, 0x00000020, spins) {
            fail = Some(I2cError::Stop);
        }
        r.write(TOKEN, Block::I2c1, 0x1c, 0x00000020 | 0x00000010);
        match fail {
            None => Ok(got),
            Some(e) => Err(e),
        }
    }
}

/// `SPI1`. It starts only from `Clocked`, and only on its solved pins.
pub struct Spi1<S> {
    _state: PhantomData<S>,
}

/// The chip selects of `SPI1`'s devices, each already an output. [`Spi1::init`]
/// takes them all, so nothing transfers on `SPI1` before every chip select of
/// the bus is driven: an undriven chip select is a selected part (`AET-WO-4200`
/// F3).
pub struct Spi1Selects {
    /// `U4`'s, net `FLASH_CS`.
    pub pa0: PA0<Output>,
}

/// The devices on `SPI1`, in the specification's order: each reference,
/// upper-cased.
#[allow(non_camel_case_types)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Spi1Device {
    /// `U4`, a `W25Q64JV`, chip select `PA0`.
    U4,
}

impl Spi1<Clocked> {
    /// Master mode, 8-bit frames, and the peripheral left disabled: each
    /// transfer enables it and disables it again. Every chip select of the bus is
    /// driven high first (deselected), whatever firmware did with it before. The
    /// baud rate, clock polarity and phase, and slave-select management are not
    /// solved yet: they stay at reset (Renode 1.17.0 does not model them).
    pub fn init<R: Registers>(
        self,
        r: &mut R,
        _sck: PA5<AlternateFunction<5>>,
        _mosi: PA7<AlternateFunction<5>>,
        _miso: PA6<AlternateFunction<5>>,
        _selects: Spi1Selects,
    ) -> Spi1<Enabled<()>> {
        r.write(TOKEN, Block::GpioA, 0x18, 0x00000001);
        r.modify(TOKEN, Block::Spi1, 0x00, |v| v & !0x00000001);
        r.modify(TOKEN, Block::Spi1, 0x08, |v| (v & !0x0000001f) | 0x00000007);
        r.modify(TOKEN, Block::Spi1, 0x0c, |v| v | 0x00400000);
        Spi1 { _state: PhantomData }
    }
}

impl Spi1<Enabled<()>> {
    /// Selects `device` (its chip select low) and only it, writes `write`, then
    /// reads `read` while it clocks out `0x00`; then disables the peripheral and
    /// deselects the device, also after a wait that expired. Every frame is one
    /// byte, and every wait is bounded by [`SPI_WAIT_SPINS`]. Returns the bytes
    /// read, or why it gave up.
    pub fn transfer<R: Registers>(
        &mut self,
        r: &mut R,
        device: Spi1Device,
        write: &[u8],
        read: &mut [u8],
    ) -> Result<usize, SpiError> {
        self.transfer_within(r, device, write, read, SPI_WAIT_SPINS)
    }

    /// [`Self::transfer`] with its own bound on each wait, so the proof can use a
    /// small one.
    #[doc(hidden)]
    pub fn transfer_within<R: Registers>(
        &mut self,
        r: &mut R,
        device: Spi1Device,
        write: &[u8],
        read: &mut [u8],
        spins: u32,
    ) -> Result<usize, SpiError> {
        let frames = match u32::try_from(write.len() + read.len()) {
            Ok(n) if n > 0 && n <= SPI_MAX_FRAMES => n,
            _ => return Err(SpiError::Length),
        };
        let (port, select, deselect) = match device {
            Spi1Device::U4 => (Block::GpioA, 0x00010000, 0x00000001),
        };
        r.write(TOKEN, Block::Spi1, 0x04, frames);
        r.write(TOKEN, port, 0x18, select);
        r.modify(TOKEN, Block::Spi1, 0x00, |v| v | 0x00000001);
        r.modify(TOKEN, Block::Spi1, 0x00, |v| v | 0x00000200);
        let mut fail = false;
        for &byte in write {
            if spi_frame(r, Block::Spi1, byte, spins).is_none() {
                fail = true;
                break;
            }
        }
        let mut got = 0;
        if !fail {
            for slot in read.iter_mut() {
                match spi_frame(r, Block::Spi1, 0x00, spins) {
                    Some(byte) => *slot = byte,
                    None => {
                        fail = true;
                        break;
                    }
                }
                got += 1;
            }
        }
        r.write(TOKEN, Block::Spi1, 0x18, 0x00000008);
        r.modify(TOKEN, Block::Spi1, 0x00, |v| v & !0x00000001);
        r.write(TOKEN, port, 0x18, deselect);
        if fail { Err(SpiError::Rxp) } else { Ok(got) }
    }
}

/// The clock gates, one method per solved port and peripheral.
pub struct Rcc {
    _private: (),
}

impl Rcc {
    /// `RCC_AHB4ENR` bit 0.
    pub fn enable_gpioa<R: Registers>(&mut self, r: &mut R, _gated: GpioA<Gated>) -> GpioA<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0e0, |v| v | 0x00000001);
        GpioA { _state: PhantomData }
    }

    /// `RCC_AHB4ENR` bit 1.
    pub fn enable_gpiob<R: Registers>(&mut self, r: &mut R, _gated: GpioB<Gated>) -> GpioB<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0e0, |v| v | 0x00000002);
        GpioB { _state: PhantomData }
    }

    /// `RCC_APB1LENR` bit 21.
    pub fn enable_i2c1<R: Registers>(&mut self, r: &mut R, _gated: I2c1<Gated>) -> I2c1<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0e8, |v| v | 0x00200000);
        I2c1 { _state: PhantomData }
    }

    /// `RCC_APB2ENR` bit 12.
    pub fn enable_spi1<R: Registers>(&mut self, r: &mut R, _gated: Spi1<Gated>) -> Spi1<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0f0, |v| v | 0x00001000);
        Spi1 { _state: PhantomData }
    }
}

/// Everything on the board, once per program.
pub struct Board {
    pub rcc: Rcc,
    pub gpioa: GpioA<Gated>,
    pub gpiob: GpioB<Gated>,
    pub i2c1: I2c1<Gated>,
    pub spi1: Spi1<Gated>,
}

static TAKEN: AtomicBool = AtomicBool::new(false);

impl Board {
    /// The board, the first time; `None` after that. The crate's one
    /// runtime check.
    pub fn take() -> Option<Board> {
        if TAKEN.swap(true, Ordering::AcqRel) {
            return None;
        }
        Some(Board {
            rcc: Rcc { _private: () },
            gpioa: GpioA { _state: PhantomData },
            gpiob: GpioB { _state: PhantomData },
            i2c1: I2c1 { _state: PhantomData },
            spi1: Spi1 { _state: PhantomData },
        })
    }
}
